<script setup lang="ts">
import { ref } from 'vue';import { authPasswordAPI } from '../../services/api';
const email=ref(''),loading=ref(false),message=ref(''),error=ref('');
async function submit(){loading.value=true;error.value='';message.value='';try{const r=await authPasswordAPI.forgotPassword(email.value);message.value=r.data?.message||r.data?.data?.message||'If an account exists, password reset instructions have been sent.';}catch(e:any){error.value=e.response?.data?.error||'Could not request a password reset.'}finally{loading.value=false}}
</script><template><main class="auth-simple"><section><h1>Forgot password?</h1><p>Enter your email address and we will send reset instructions.</p><div v-if="message" class="success" role="status">{{message}}</div><div v-if="error" class="error" role="alert">{{error}}</div><form @submit.prevent="submit"><label>Email<input v-model="email" type="email" required :disabled="loading" /></label><button :disabled="loading">{{loading?'Sending...':'Send reset link'}}</button></form><router-link to="/login">Back to sign in</router-link></section></main></template><style scoped>.auth-simple{min-height:78vh;display:grid;place-items:center;padding:20px}.auth-simple section{width:min(420px,100%);padding:28px;border:1px solid #e4e9ef;border-radius:8px}.auth-simple h1{margin:0 0 8px;color:#0f2a44}.auth-simple p{color:#64748b}.auth-simple form{display:flex;flex-direction:column;gap:12px;margin-top:18px}.auth-simple label{display:flex;flex-direction:column;gap:7px;font-weight:700}.auth-simple input{height:44px;padding:0 12px;border:1px solid #cbd5e1;border-radius:6px}.auth-simple button{height:44px;border:0;border-radius:6px;background:#075397;color:#fff;font-weight:800}.auth-simple section>a{display:block;margin-top:16px;color:#075397}.success,.error{padding:10px;border-radius:6px}.success{background:#e8f7ef;color:#18794e}.error{background:#feeaea;color:#b42318}</style>